import StaffManagementStaffPageClient from './staff-management-page-client'
import { getPropertyForUser } from '@/lib/dashboard/property-access'
import { resolveDashboardNavVisibility } from '@/lib/dashboard/dashboard-layout-context'
import { createClient } from '@/lib/supabase/server'
import { redirect } from 'next/navigation'

type pageProps = {
  params: Promise<{ propertyId: string }>
}

export default async function StaffManagementPage({ params }: pageProps) {
  const { propertyId } = await params
  const property = await getPropertyForUser(propertyId)
  if (!property) redirect('/auth/login')

  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) redirect('/auth/login')

  const navVisibility = await resolveDashboardNavVisibility(supabase, propertyId, user.id)
  if (!navVisibility.moduleNavVisible['staff-management']) {
    redirect(`/dashboard/${propertyId}/access-denied`)
  }

  return <StaffManagementStaffPageClient propertyName={property.name} />
}

'use client'

import { useCallback, useEffect, useState } from 'react'
import { useParams, useRouter } from 'next/navigation'
import StaffManagementPageHeader from '@/components/dashboard/staff-management/staff-management-page-header'
import {
  StaffManagementCategoriesDialog,
  type CategoryRow,
  type RoleId,
} from '@/components/dashboard/staff-management/staff-management-dialog/staff-management-categories-dialog'
import { useToast } from '@/hooks/use-toast'
import InviteStaffDialog from '@/components/dashboard/staff-management/staff-management-dialog/invite-staff-dialog'
import { StaffAccessDialog } from '@/components/dashboard/staff-management/staff-management-dialog/staff-access-dialog'
import {
  EditStaffDialog,
  type EditStaffDialogStaff,
} from '@/components/dashboard/staff-management/staff-management-dialog/edit-staff-dialog'
import {
  DeactivateStaffDialog,
  type DeactivateStaffDialogTarget,
} from '@/components/dashboard/staff-management/staff-management-dialog/deactivate-staff-dialog'
import {
  StaffDetailsDialog,
  type StaffDetailsDialogTarget,
} from '@/components/dashboard/staff-management/staff-management-dialog/staff-details-dialog'
import { StaffManagementTable } from '@/components/dashboard/staff-management/staff-management-table'
import StaffManagementFilter, {
  type StaffManagementFilterValue,
} from '@/components/dashboard/staff-management/staff-management-filter'

type StaffManagementStaffPageClientProps = {
  propertyName: string
}

const FILTER_DEBOUNCE_MS = 300

export default function StaffManagementStaffPageClient({
  propertyName,
}: StaffManagementStaffPageClientProps) {
  const params = useParams<{ propertyId: string }>()
  const propertyId =
    typeof params.propertyId === 'string'
      ? params.propertyId
      : Array.isArray(params.propertyId)
        ? (params.propertyId[0] ?? '')
        : ''
  const router = useRouter()
  const { toast } = useToast()
  const [categoriesOpen, setCategoriesOpen] = useState(false)
  const [staffAccessOpen, setStaffAccessOpen] = useState(false)
  const [inviteStaffOpen, setInviteStaffOpen] = useState(false)
  const [staffDetailsOpen, setStaffDetailsOpen] = useState(false)
  const [staffDetailsTarget, setStaffDetailsTarget] = useState<StaffDetailsDialogTarget | null>(null)
  const [editStaffOpen, setEditStaffOpen] = useState(false)
  const [editStaffTarget, setEditStaffTarget] = useState<EditStaffDialogStaff | null>(null)
  const [deactivateStaffOpen, setDeactivateStaffOpen] = useState(false)
  const [deactivateStaffTarget, setDeactivateStaffTarget] =
    useState<DeactivateStaffDialogTarget | null>(null)
  const [isSavingCategories, setIsSavingCategories] = useState(false)
  const [staffTableReloadKey, setStaffTableReloadKey] = useState(0)
  const [filterValue, setFilterValue] = useState<StaffManagementFilterValue>({
    search: '',
    role: 'all',
    category: 'all',
    status: 'all',
  })
  const [debouncedFilterValue, setDebouncedFilterValue] =
    useState<StaffManagementFilterValue>(filterValue)
  const [filterOptions, setFilterOptions] = useState<{
    roles: string[]
    categories: string[]
    statuses: string[]
  }>({
    roles: [],
    categories: [],
    statuses: [],
  })

  useEffect(() => {
    const timeoutId = window.setTimeout(() => {
      setDebouncedFilterValue(filterValue)
    }, FILTER_DEBOUNCE_MS)

    return () => {
      window.clearTimeout(timeoutId)
    }
  }, [filterValue])

  const handleReactivateStaff = useCallback(
    async (target: { id: string; name: string }) => {
      try {
        const res = await fetch(
          `/api/v1/properties/${propertyId}/staff-management/staff/${target.id}`,
          {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ status: 'active' }),
          },
        )
        const json: { success?: boolean; error?: { message?: string } } = await res.json().catch(() => ({}))
        if (!res.ok || json.success !== true) {
          throw new Error(json.error?.message ?? 'Failed to reactivate staff member')
        }
        toast({ title: 'Staff member reactivated', description: `${target.name} can access this property again.` })
        setStaffTableReloadKey((k) => k + 1)
        router.refresh()
      } catch (err: unknown) {
        const message = err instanceof Error ? err.message : 'Unknown error'
        toast({
          title: 'Reactivation failed',
          description: message,
          variant: 'destructive',
        })
      }
    },
    [propertyId, router, toast],
  )

  const handleSaveCategories = async (categoriesByRole: Record<RoleId, CategoryRow[]>) => {
    if (isSavingCategories) return

    try {
      setIsSavingCategories(true)
      const res = await fetch(
        `/api/v1/properties/${propertyId}/staff-management/categories`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            categoriesByRole: {
              admin: categoriesByRole.admin.map((c) => ({ name: c.name })),
              manager: categoriesByRole.manager.map((c) => ({ name: c.name })),
              staff: categoriesByRole.staff.map((c) => ({ name: c.name })),
            },
          }),
        },
      )

      const json: any = await res.json().catch(() => null)
      if (!res.ok || json?.success !== true) {
        console.error('[StaffManagement] Save categories failed', {
          url: `/api/v1/properties/${propertyId}/staff-management/categories`,
          status: res.status,
          statusText: res.statusText,
          response: json,
        })
        throw new Error(json?.error?.message ?? 'Failed to save categories')
      }

      toast({ title: 'Categories saved' })
      router.refresh()
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : 'Unknown error'
      toast({
        title: 'Failed to save categories',
        description: message,
        variant: 'destructive',
      })
    } finally {
      setIsSavingCategories(false)
    }
  }

  return (
    <>
      <div className="space-y-4 sm:space-y-6 px-6 pb-8">
        <StaffManagementPageHeader
          propertyName={propertyName}
          onAccessClick={() => setStaffAccessOpen(true)}
          onCategoriesClick={() => setCategoriesOpen(true)}
          onInviteStaffClick={() => setInviteStaffOpen(true)}
        />

        <StaffManagementFilter
          value={filterValue}
          onChange={setFilterValue}
          roleOptions={filterOptions.roles}
          categoryOptions={filterOptions.categories}
          statusOptions={filterOptions.statuses}
        />

        <StaffManagementTable
          propertyId={propertyId}
          reloadKey={staffTableReloadKey}
          search={debouncedFilterValue.search}
          role={debouncedFilterValue.role}
          category={debouncedFilterValue.category}
          status={debouncedFilterValue.status}
          onFilterOptionsChange={setFilterOptions}
          onViewStaff={(staffMember: StaffDetailsDialogTarget) => {
            setStaffDetailsTarget(staffMember)
            setStaffDetailsOpen(true)
          }}
          onEditStaff={(staffMember: EditStaffDialogStaff) => {
            setEditStaffTarget(staffMember)
            setEditStaffOpen(true)
          }}
          onDeactivateStaff={(target: DeactivateStaffDialogTarget) => {
            setDeactivateStaffTarget(target)
            setDeactivateStaffOpen(true)
          }}
          onReactivateStaff={handleReactivateStaff}
        />
      </div>

      <StaffAccessDialog
        open={staffAccessOpen}
        onOpenChange={setStaffAccessOpen}
        propertyId={propertyId}
      />

      <StaffManagementCategoriesDialog
        open={categoriesOpen}
        onOpenChange={setCategoriesOpen}
        onSave={handleSaveCategories}
        propertyId={propertyId}
      />

      <InviteStaffDialog
        open={inviteStaffOpen}
        onOpenChange={setInviteStaffOpen}
        propertyId={propertyId}
        onInviteSent={() => setStaffTableReloadKey((k) => k + 1)}
      />

      <StaffDetailsDialog
        open={staffDetailsOpen}
        onOpenChange={(next) => {
          setStaffDetailsOpen(next)
          if (!next) setStaffDetailsTarget(null)
        }}
        staff={staffDetailsTarget}
      />

      <EditStaffDialog
        open={editStaffOpen}
        onOpenChange={(next) => {
          setEditStaffOpen(next)
          if (!next) setEditStaffTarget(null)
        }}
        propertyId={propertyId}
        propertyName={propertyName}
        staff={editStaffTarget}
        onSaved={() => setStaffTableReloadKey((k) => k + 1)}
      />

      <DeactivateStaffDialog
        open={deactivateStaffOpen}
        onOpenChange={(next) => {
          setDeactivateStaffOpen(next)
          if (!next) setDeactivateStaffTarget(null)
        }}
        propertyId={propertyId}
        staff={deactivateStaffTarget}
        onDeactivated={() => setStaffTableReloadKey((k) => k + 1)}
      />
    </>
  )
}

"use client"

import { useCallback, useEffect, useState } from "react"
import { Eye, Pencil, UserCheck, UserMinus } from "lucide-react"
import type { EditStaffDialogStaff } from "@/components/dashboard/staff-management/staff-management-dialog/edit-staff-dialog"
import type { DeactivateStaffDialogTarget } from "@/components/dashboard/staff-management/staff-management-dialog/deactivate-staff-dialog"
import type { StaffDetailsDialogTarget } from "@/components/dashboard/staff-management/staff-management-dialog/staff-details-dialog"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { useToast } from "@/hooks/use-toast"
import { isAccessDeniedError } from "@/lib/utils/is-access-denied-error"
import { PermissionGate } from "@/components/ui/permission-gate"

type StaffRow = {
  id: string
  name: string
  email: string
  role: "Owner" | "Admin" | "Manager" | "Staff"
  categories: string[] | "All Categories"
  status: "Active" | "Pending" | "Inactive"
  lastLogin: string
}

type StaffManagementTableProps = {
  propertyId: string
  reloadKey?: number
  search?: string
  role?: string
  category?: string
  status?: string
  onFilterOptionsChange?: (options: {
    roles: string[]
    categories: string[]
    statuses: string[]
  }) => void
  onEditStaff?: (staff: EditStaffDialogStaff) => void
  onViewStaff?: (staff: StaffDetailsDialogTarget) => void
  onDeactivateStaff?: (staff: DeactivateStaffDialogTarget) => void
  onReactivateStaff?: (staff: { id: string; name: string }) => void
}

function initialsFromName(name: string): string {
  const trimmed = name.trim()
  if (!trimmed || trimmed === "—") return "N"
  const words = trimmed.split(/\s+/).filter(Boolean)
  const first = words[0]?.[0] ?? ""
  const last = words.length > 1 ? words[words.length - 1]?.[0] ?? "" : ""
  return `${first}${last}`.toUpperCase() || "N"
}

function StatusPill({ status }: { status: StaffRow["status"] }) {
  const base =
    "inline-flex items-center rounded-full px-3 py-1 text-xs font-medium border whitespace-nowrap"

  if (status === "Active") {
    return <span className={`${base} border-emerald-200 bg-emerald-50 text-emerald-700`}>Active</span>
  }

  if (status === "Pending") {
    return <span className={`${base} border-amber-200 bg-amber-50 text-amber-700`}>Pending</span>
  }

  return <span className={`${base} border-muted bg-background text-muted-foreground`}>Inactive</span>
}

function RolePill({ role }: { role: StaffRow["role"] }) {
  return (
    <Badge
      variant="secondary"
      className="rounded-full bg-muted text-foreground font-medium normal-case border border-muted-foreground/10 px-3 py-1"
    >
      {role}
    </Badge>
  )
}

function CategoryChips({ categories }: { categories: StaffRow["categories"] }) {
  if (categories === "All Categories") {
    return (
      <Badge
        variant="secondary"
        className="rounded-full bg-muted/60 text-foreground font-medium normal-case border border-muted-foreground/10"
      >
        All Categories
      </Badge>
    )
  }

  if (categories.length === 0) {
    return <span className="text-muted-foreground">—</span>
  }

  return (
    <div className="flex flex-wrap gap-2">
      {categories.map((c) => (
        <Badge
          key={c}
          variant="secondary"
          className="rounded-full bg-muted/60 text-foreground font-medium normal-case border border-muted-foreground/10"
        >
          {c}
        </Badge>
      ))}
    </div>
  )
}

export function StaffManagementTable({
  propertyId,
  reloadKey = 0,
  search = "",
  role = "all",
  category = "all",
  status = "all",
  onFilterOptionsChange,
  onEditStaff,
  onViewStaff,
  onDeactivateStaff,
  onReactivateStaff,
}: StaffManagementTableProps) {
  const [rows, setRows] = useState<StaffRow[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)
  const { toast } = useToast()

  const loadStaff = useCallback(async () => {
    setLoading(true)
    setLoadError(null)
    try {
      const res = await fetch(
        `/api/v1/properties/${propertyId}/staff-management/staff`,
        { method: "GET" },
      )
      const json: { success?: boolean; data?: { staff?: StaffRow[] }; error?: { message?: string } } =
        await res.json().catch(() => ({}))
      if (!res.ok || json.success !== true) {
        throw new Error(json.error?.message ?? "Failed to load staff")
      }
      setRows(Array.isArray(json.data?.staff) ? json.data!.staff! : [])
    } catch (e: unknown) {
      setRows([])
      if (isAccessDeniedError(e)) {
        setLoadError('Access denied')
        toast({
          title: 'Access denied',
          description: "You don't have permission to view staff. Contact your property administrator if you believe this is an error.",
          variant: 'destructive',
        })
      } else {
        setLoadError(e instanceof Error ? e.message : "Failed to load staff")
      }
    } finally {
      setLoading(false)
    }
  }, [propertyId])

  useEffect(() => {
    void loadStaff()
  }, [loadStaff, reloadKey])

  useEffect(() => {
    if (!onFilterOptionsChange) return

    const roleSet = new Set<string>()
    const categorySet = new Set<string>()
    const statusSet = new Set<string>()

    for (const row of rows) {
      roleSet.add(row.role)
      statusSet.add(row.status)

      if (row.categories === "All Categories") {
        categorySet.add("All Categories")
      } else {
        for (const categoryName of row.categories) {
          categorySet.add(categoryName)
        }
      }
    }

    onFilterOptionsChange({
      roles: Array.from(roleSet).sort(),
      categories: Array.from(categorySet).sort(),
      statuses: Array.from(statusSet).sort(),
    })
  }, [onFilterOptionsChange, rows])

  const normalizedSearch = search.trim().toLowerCase()
  const filteredRows = rows.filter((row) => {
    const matchesSearch =
      normalizedSearch.length === 0 ||
      row.name.toLowerCase().includes(normalizedSearch) ||
      row.email.toLowerCase().includes(normalizedSearch)

    const matchesRole = role === "all" || row.role === role
    const matchesStatus = status === "all" || row.status === status

    const matchesCategory =
      category === "all" ||
      (row.categories === "All Categories"
        ? category === "All Categories"
        : row.categories.includes(category))

    return matchesSearch && matchesRole && matchesStatus && matchesCategory
  })

  return (
    <div className="border border-border/80 bg-card/50">
      {loadError ? (
        <div className="p-4 text-sm text-destructive">{loadError}</div>
      ) : null}
      <Table className="text-xs">
        <TableHeader className="sticky top-0 z-10 bg-red-50 dark:bg-red-950/30 uppercase">
          <TableRow className="h-8 hover:bg-transparent data-[state=selected]:bg-transparent">
            <TableHead className="w-[320px] py-1.5 dark:text-white/90 text-black/90 font-medium">
              Member
            </TableHead>
            <TableHead className="w-[140px] py-1.5 dark:text-white/90 text-black/90 font-medium">
              Role
            </TableHead>
            <TableHead className="py-1.5 dark:text-white/90 text-black/90 font-medium">
              Categories
            </TableHead>
            <TableHead className="w-[140px] py-1.5 dark:text-white/90 text-black/90 font-medium">
              Status
            </TableHead>
            <TableHead className="w-[180px] py-1.5 dark:text-white/90 text-black/90 font-medium">
              Last Login
            </TableHead>
            <TableHead className="w-[140px] py-1.5 text-right dark:text-white/90 text-black/90 font-medium">
              Actions
            </TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {loading ? (
            <TableRow>
              <TableCell colSpan={6} className="py-8 text-center text-muted-foreground">
                Loading staff…
              </TableCell>
            </TableRow>
          ) : filteredRows.length === 0 ? (
            <TableRow>
              <TableCell colSpan={6} className="py-8 text-center text-muted-foreground">
                No staff matches the selected filters.
              </TableCell>
            </TableRow>
          ) : (
            filteredRows.map((row) => (
              <TableRow
                key={row.id}
                className="border-border/80 hover:bg-muted/30 data-[state=selected]:bg-muted/30"
              >
                <TableCell className="py-1.5">
                  <div className="flex items-center gap-3">
                    <Avatar className="h-10 w-10">
                      <AvatarFallback className="bg-blue-50 text-blue-700 font-semibold">
                        {initialsFromName(row.name)}
                      </AvatarFallback>
                    </Avatar>
                    <div className="min-w-0">
                      <div className="font-semibold text-foreground truncate">{row.name}</div>
                      <div className="text-sm text-muted-foreground truncate">{row.email}</div>
                    </div>
                  </div>
                </TableCell>
                <TableCell className="py-1.5 whitespace-nowrap">
                  <RolePill role={row.role} />
                </TableCell>
                <TableCell className="py-1.5">
                  <CategoryChips categories={row.categories} />
                </TableCell>
                <TableCell className="py-1.5">
                  <StatusPill status={row.status} />
                </TableCell>
                <TableCell className="py-1.5 text-sm text-muted-foreground whitespace-nowrap">
                  {row.lastLogin}
                </TableCell>
                <TableCell className="py-0.5">
                  <div className="flex items-center justify-end gap-2">
                    <Button
                      variant="ghost"
                      size="xs"
                      aria-label="View staff"
                      className="h-8 w-8 p-0"
                      onClick={() =>
                        onViewStaff?.({
                          id: row.id,
                          name: row.name,
                          email: row.email,
                          role: row.role,
                          categories: row.categories,
                          status: row.status,
                          lastLogin: row.lastLogin,
                        })
                      }
                    >
                      <Eye className="h-4 w-4" />
                    </Button>
                    <PermissionGate permission="global.change_staff_role">
                      <Button
                        variant="ghost"
                        size="xs"
                        aria-label="Edit staff"
                        className="h-8 w-8 p-0"
                        disabled={row.role === "Owner"}
                        title={row.role === "Owner" ? "Owner role cannot be edited here" : "Edit role and access"}
                        onClick={() =>
                          onEditStaff?.({
                            id: row.id,
                            name: row.name,
                            role: row.role,
                            categories: row.categories,
                          })
                        }
                      >
                        <Pencil className="h-4 w-4" />
                      </Button>
                    </PermissionGate>
                    <PermissionGate permission="global.deactivate_staff">
                      {row.status === "Inactive" ? (
                        <Button
                          variant="ghost"
                          size="xs"
                          aria-label="Reactivate staff"
                          className="h-8 w-8 p-0 text-emerald-600 hover:text-emerald-700 dark:text-emerald-400 dark:hover:text-emerald-300"
                          disabled={row.role === "Owner"}
                          title={
                            row.role === "Owner"
                              ? "Owner status cannot be changed here"
                              : "Restore access for this staff member"
                          }
                          onClick={() => onReactivateStaff?.({ id: row.id, name: row.name })}
                        >
                          <UserCheck className="h-4 w-4" />
                        </Button>
                      ) : (
                        <Button
                          variant="ghost"
                          size="xs"
                          aria-label="Deactivate staff"
                          className="h-8 w-8 p-0 text-red-500 hover:text-red-600"
                          disabled={row.role === "Owner"}
                          title={
                            row.role === "Owner"
                              ? "Owner cannot be deactivated"
                              : "Deactivate staff member"
                          }
                          onClick={() =>
                            onDeactivateStaff?.({
                              id: row.id,
                              name: row.name,
                              status: row.status,
                            })
                          }
                        >
                          <UserMinus className="h-4 w-4" />
                        </Button>
                      )}
                    </PermissionGate>
                  </div>
                </TableCell>
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>
    </div>
  )
}

import { type NextRequest } from 'next/server'
import { createSupabaseClientForApiRoute } from '@/lib/supabase/api-route-client'
import { createServiceRoleClient } from '@/lib/supabase/service-role'
import { success, error } from '@/lib/api/response'
import { ErrorCodes } from '@/lib/api/errors'
import { requirePropertyAccess, isDenied } from '@/lib/rbac'
import { StaffManagementQueries } from '@/lib/dashboard/staff-management-queries'

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ propertyId: string }> },
) {
  try {
    const { propertyId } = await params
    const { supabase, user, error: authError } = await createSupabaseClientForApiRoute(request)

    if (authError || !user) {
      return error(ErrorCodes.AUTH_001, request)
    }

    const access = await requirePropertyAccess(supabase as any, user.id, {
      propertyId,
      minimumRole: 'manager',
    })
    if (isDenied(access)) return access

    const q = new StaffManagementQueries(supabase as any)
    const admin = createServiceRoleClient()
    const staff = await q.listStaffForManagementTable(propertyId, admin)

    return success({ staff }, request)
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown error'
    return error(ErrorCodes.INTERNAL_ERROR, request, { message })
  }
}

import type { SupabaseClient } from '@supabase/supabase-js'
import { createClient } from '@/lib/supabase/server'
import { isElevatedPropertyStaffRole } from '@/lib/dashboard/property-staff-roles'

export type UiRole = 'owner' | 'admin' | 'manager' | 'staff'
type DbRole = 'owner' | 'admin' | 'manager' | 'staff'

export type RoleCategoryAccess = {
  selectedModuleKey?: string
  moduleAccessControl?: Record<string, Record<string, boolean>>
}

const roleMap: Record<UiRole, DbRole> = {
  owner: 'owner',
  admin: 'admin',
  manager: 'manager',
  staff: 'staff',
}

export type StaffManagementTableRow = {
  id: string
  name: string
  email: string
  role: 'Owner' | 'Admin' | 'Manager' | 'Staff'
  categories: string[] | 'All Categories'
  status: 'Active' | 'Pending' | 'Inactive'
  lastLogin: string
}

function formatStaffTableRoleLabel(dbRole: string): StaffManagementTableRow['role'] {
  const r = dbRole.toLowerCase()
  if (r === 'owner') return 'Owner'
  if (r === 'admin' || r === 'property_admin') return 'Admin'
  if (r === 'manager') return 'Manager'
  return 'Staff'
}

function formatStaffTableStatus(raw: string): StaffManagementTableRow['status'] {
  const s = raw.toLowerCase()
  if (s === 'pending') return 'Pending'
  if (s === 'inactive') return 'Inactive'
  return 'Active'
}

function formatStaffTableLastLogin(iso: string | undefined): string {
  if (!iso) return 'Never'
  try {
    return new Date(iso).toLocaleString(undefined, {
      dateStyle: 'medium',
      timeStyle: 'short',
    })
  } catch {
    return 'Never'
  }
}

function formatStaffInviteRoleLabel(dbRole: string): string {
  const r = dbRole.toLowerCase()
  if (r === 'owner') return 'Owner'
  if (r === 'admin' || r === 'property_admin') return 'Admin'
  if (r === 'manager') return 'Manager'
  if (r === 'staff') return 'Staff'
  return dbRole ? dbRole.charAt(0).toUpperCase() + dbRole.slice(1) : '—'
}

export { isElevatedPropertyStaffRole } from '@/lib/dashboard/property-staff-roles'

export class StaffManagementQueries {
  constructor(private readonly supabase: SupabaseClient) {}

  static async create(): Promise<StaffManagementQueries> {
    const supabase = await createClient()
    return new StaffManagementQueries(supabase as unknown as SupabaseClient)
  }

  async verifyPropertyAccess(input: {
    propertyId: string
    userId: string
  }): Promise<{ hasAccess: boolean; isAdmin: boolean }> {
    const { data: property } = await this.supabase
      .from('properties')
      .select('company_id')
      .eq('id', input.propertyId)
      .single()

    if (!property) {
      return { hasAccess: false, isAdmin: false }
    }

    const { data: company } = await this.supabase
      .from('companies')
      .select('owner_id')
      .eq('id', property.company_id)
      .single()

    if (company?.owner_id === input.userId) {
      return { hasAccess: true, isAdmin: true }
    }

    const { data: staffRecord } = await this.supabase
      .from('property_staff')
      .select('role')
      .eq('property_id', input.propertyId)
      .eq('user_id', input.userId)
      .single()

    if (staffRecord) {
      const isAdmin = isElevatedPropertyStaffRole(staffRecord.role)
      return { hasAccess: true, isAdmin }
    }

    return { hasAccess: false, isAdmin: false }
  }

  async getPropertyRoleCategories(input: {
    propertyId: string
  }): Promise<{ categoriesByRole: Record<UiRole, { id: string; name: string; access: RoleCategoryAccess }[]> }> {
    const { data, error: selectError } = await this.supabase
      .from('property_role_categories')
      .select('id, role, name, access')
      .eq('property_id', input.propertyId)
      .in('role', ['owner', 'admin', 'manager', 'staff'])
      .order('name', { ascending: true })

    if (selectError) {
      console.error('[StaffManagementQueries] Failed to fetch role categories', {
        propertyId: input.propertyId,
        error: selectError,
      })
      throw selectError
    }

    const grouped: Record<UiRole, { id: string; name: string; access: RoleCategoryAccess }[]> = {
      owner: [],
      admin: [],
      manager: [],
      staff: [],
    }

    for (const row of data ?? []) {
      const role = row.role as UiRole
      if (role !== 'owner' && role !== 'admin' && role !== 'manager' && role !== 'staff') continue
      grouped[role].push({
        id: row.id,
        name: row.name,
        access: (row.access as RoleCategoryAccess) ?? {},
      })
    }

    return { categoriesByRole: grouped }
  }

  async savePropertyRolesCategories(input: {
    propertyId: string
    categoriesByRole: Record<UiRole, { name: string }[]>
  }): Promise<{ savedCount: number }> {
    const roles: DbRole[] = ['owner', 'admin', 'manager', 'staff']

    const { data: existing, error: existingError } = await this.supabase
      .from('property_role_categories')
      .select('id, role, name, access')
      .eq('property_id', input.propertyId)
      .in('role', roles)

    if (existingError) {
      console.error('[StaffManagementQueries] Failed to load existing categories', {
        propertyId: input.propertyId,
        error: existingError,
      })
      throw existingError
    }

    const existingAccessByKey = new Map(
      (existing ?? []).map((r) => [`${r.role}::${r.name}`, (r.access as RoleCategoryAccess) ?? {}]),
    )

    const desired = (Object.keys(input.categoriesByRole) as UiRole[]).flatMap(
      (uiRole) => {
        const role = roleMap[uiRole]
        return input.categoriesByRole[uiRole].map((c) => {
          const name = c.name.trim()
          return {
            property_id: input.propertyId,
            role,
            name,
            access: existingAccessByKey.get(`${role}::${name}`) ?? {},
          }
        })
      },
    )

    const desiredKey = new Set(desired.map((r) => `${r.role}::${r.name}`))
    const toDeleteIds = (existing ?? [])
      .filter((r) => !desiredKey.has(`${r.role}::${r.name}`))
      .map((r) => r.id)

    if (toDeleteIds.length > 0) {
      const { error: deleteError } = await this.supabase
        .from('property_role_categories')
        .delete()
        .eq('property_id', input.propertyId)
        .in('id', toDeleteIds)

      if (deleteError) {
        console.error('[StaffManagementQueries] Failed to delete categories', {
          propertyId: input.propertyId,
          toDeleteIds,
          error: deleteError,
        })
        throw deleteError
      }
    }

    const { error: upsertError } = await this.supabase
      .from('property_role_categories')
      .upsert(desired, { onConflict: 'property_id,role,name' })

    if (upsertError) {
      console.error('[StaffManagementQueries] Failed to upsert categories', {
        propertyId: input.propertyId,
        desiredCount: desired.length,
        error: upsertError,
      })
      throw upsertError
    }

    return { savedCount: desired.length }
  }

  async savePropertyRoleCategoryAccess(input: {
    propertyId: string
    categoryId: string
    role: UiRole
    access: RoleCategoryAccess
  }): Promise<void> {
    const { error: upErr } = await this.supabase
      .from('property_role_categories')
      .update({ access: input.access })
      .eq('id', input.categoryId)
      .eq('property_id', input.propertyId)
      .eq('role', roleMap[input.role])

    if (upErr) {
      console.error('[StaffManagementQueries] Failed to save role category access', {
        propertyId: input.propertyId,
        categoryId: input.categoryId,
        role: input.role,
        error: upErr,
      })
      throw upErr
    }
  }

