  async getStaffInviteStaffContextByUserId(userId: string): Promise<{
    roleLabel: string
    categoryNames: string[]
  }> {
    const { data: staffRows, error: staffError } = await this.supabase
      .from('property_staff')
      .select('role, role_category_id, property_id, status, created_at')
      .eq('user_id', userId)
      .order('created_at', { ascending: false })
      .limit(10)

    if (staffError) {
      console.error('[StaffManagementQueries] Failed to load staff for invite', {
        userId,
        error: staffError,
      })
      throw staffError
    }

    const staffRow =
      staffRows?.find((r) => r.status === 'pending') ?? staffRows?.[0] ?? null

    if (!staffRow?.property_id) {
      return { roleLabel: '—', categoryNames: [] }
    }

    const roleLabel = formatStaffInviteRoleLabel(staffRow.role ?? '')
    const ids: string[] = staffRow.role_category_id ?? []
    if (ids.length === 0) {
      return { roleLabel, categoryNames: [] }
    }

    const { data: cats, error: catErr } = await this.supabase
      .from('property_role_categories')
      .select('id, name')
      .eq('property_id', staffRow.property_id)
      .in('id', ids)

    if (catErr) {
      console.error(
        '[StaffManagementQueries] Failed to load categories for staff invite',
        {
          propertyId: staffRow.property_id,
          userId,
          error: catErr,
        },
      )
      throw catErr
    }

    const byId = new Map(
      (cats ?? []).map((c: { id: string; name: string }) => [c.id, c.name]),
    )
    const categoryNames = ids
      .map((id: string) => byId.get(id))
      .filter((n: string | undefined): n is string => Boolean(n))

    return { roleLabel, categoryNames }
  }

  async activatePendingStaffForUser(userId: string): Promise<void> {
    const { error } = await this.supabase
      .from('property_staff')
      .update({ status: 'active' })
      .eq('user_id', userId)
      .eq('status', 'pending')

    if (error) {
      console.error('[StaffManagementQueries] Failed to activate pending staff for user', {
        userId,
        error,
      })
      throw error
    }
  }

  async listStaffForManagementTable(
    propertyId: string,
    adminClient: SupabaseClient,
  ): Promise<StaffManagementTableRow[]> {
    const rows = await this.listPropertyStaff(propertyId)

    const { data: catRows, error: catErr } = await this.supabase
      .from('property_role_categories')
      .select('id, name')
      .eq('property_id', propertyId)

    if (catErr) {
      console.error('[StaffManagementQueries] Failed to load category names for staff table', {
        propertyId,
        error: catErr,
      })
      throw catErr
    }

    const categoryNameById = new Map(
      (catRows ?? []).map((c) => [c.id, c.name] as const),
    )

    return Promise.all(
      rows.map(async (row) => {
        const userId = row.user_id
        let email = ''
        let displayName = '—'
        let lastSignIn: string | undefined

        if (userId) {
          const { data: authData, error: authErr } =
            await adminClient.auth.admin.getUserById(userId)
          if (!authErr && authData.user) {
            const u = authData.user
            email = u.email ?? ''
            const meta = u.user_metadata as Record<string, unknown> | undefined
            const fromFullOrName =
              typeof meta?.full_name === 'string'
                ? meta.full_name
                : typeof meta?.name === 'string'
                  ? meta.name
                  : ''
            const first =
              typeof meta?.first_name === 'string' ? meta.first_name.trim() : ''
            const last =
              typeof meta?.last_name === 'string' ? meta.last_name.trim() : ''
            const fromParts = [first, last].filter(Boolean).join(' ')
            const resolved = fromFullOrName.trim() || fromParts.trim()
            displayName = resolved || '—'
            lastSignIn = u.last_sign_in_at ?? undefined
          }
        }

        const ids = row.role_category_id ?? []
        const categories: string[] | 'All Categories' =
          ids.length === 0
            ? 'All Categories'
            : ids
                .map((id) => categoryNameById.get(id))
                .filter((n): n is string => Boolean(n))

        return {
          id: row.id,
          name: displayName,
          email: email || '—',
          role: formatStaffTableRoleLabel(row.role),
          categories,
          status: formatStaffTableStatus(row.status),
          lastLogin: formatStaffTableLastLogin(lastSignIn),
        }
      }),
    )
  }

  async findAuthUserIdByEmail(
    adminClient: SupabaseClient,
    email: string,
  ): Promise<string | null> {
    const normalized = email.toLowerCase()
    let page = 1
    const perPage = 200

    for (;;) {
      const { data, error: listError } = await adminClient.auth.admin.listUsers({
        page,
        perPage,
      })

      if (listError) {
        throw new Error(listError.message)
      }

      const match = data.users.find(
        (u) => (u.email ?? '').toLowerCase() === normalized,
      )
      if (match?.id) return match.id

      if (data.nextPage == null) break
      page = data.nextPage
    }

    return null
  }

  async inviteStaff(input: {
    propertyId: string
    userId: string
    role: UiRole
    roleCategoryIds: string[]
    status: 'pending' | 'active' | 'inactive'
  }): Promise<{ invitedCount: number }> {
    const { data: existingStaff } = await this.supabase
      .from('property_staff')
      .select('id')
      .eq('property_id', input.propertyId)
      .eq('user_id', input.userId)
      .single()

    if (existingStaff) {
      console.error('[StaffManagementQueries] Staff already exists', {
        propertyId: input.propertyId,
        userId: input.userId,
      })
      throw new Error('Staff already exists')
    }

    const { error: insertError } = await this.supabase
      .from('property_staff')
      .insert({
        property_id: input.propertyId,
        user_id: input.userId,
        role: roleMap[input.role],
        role_category_id: input.roleCategoryIds,
        status: input.status,
        permissions: [],
      })

    if (insertError) {
      console.error('[StaffManagementQueries] Failed to insert staff', {
        propertyId: input.propertyId,
        userId: input.userId,
        error: insertError,
      })
      throw insertError
    }

    return { invitedCount: 1 }
  }

  async updatePropertyStaffAssignment(input: {
    propertyId: string
    staffId: string
    role: 'admin' | 'manager' | 'staff'
    allCategories: boolean
    roleCategoryIds: string[]
  }): Promise<void> {
    const { data: row, error: fetchErr } = await this.supabase
      .from('property_staff')
      .select('id, role')
      .eq('id', input.staffId)
      .eq('property_id', input.propertyId)
      .maybeSingle()

    if (fetchErr) {
      console.error('[StaffManagementQueries] Failed to load staff row for update', {
        propertyId: input.propertyId,
        staffId: input.staffId,
        error: fetchErr,
      })
      throw fetchErr
    }

    if (!row) {
      throw new Error('Staff assignment not found')
    }

    const currentRole = (row.role ?? '').toLowerCase()
    if (currentRole === 'owner') {
      throw new Error('Cannot change property owner from staff management')
    }

    const nextCategoryIds = input.allCategories ? [] : [...new Set(input.roleCategoryIds)]

    if (!input.allCategories) {
      if (nextCategoryIds.length === 0) {
        throw new Error('Select at least one category, or choose All Categories')
      }

      const { data: cats, error: catErr } = await this.supabase
        .from('property_role_categories')
        .select('id, role')
        .eq('property_id', input.propertyId)
        .in('id', nextCategoryIds)

      if (catErr) {
        console.error('[StaffManagementQueries] Failed to validate role categories', {
          propertyId: input.propertyId,
          error: catErr,
        })
        throw catErr
      }

      if (!cats || cats.length !== nextCategoryIds.length) {
        throw new Error('One or more category ids are invalid for this property')
      }

      for (const c of cats) {
        const cr = String(c.role ?? '').toLowerCase()
        const matchesAdmin = input.role === 'admin' && (cr === 'admin' || cr === 'property_admin')
        const matchesOther = input.role !== 'admin' && cr === input.role
        if (!matchesAdmin && !matchesOther) {
          throw new Error('Each selected category must belong to the chosen role')
        }
      }
    }

    const { error: upErr } = await this.supabase
      .from('property_staff')
      .update({
        role: input.role,
        role_category_id: nextCategoryIds,
      })
      .eq('id', input.staffId)
      .eq('property_id', input.propertyId)

    if (upErr) {
      console.error('[StaffManagementQueries] Failed to update property staff', {
        propertyId: input.propertyId,
        staffId: input.staffId,
        error: upErr,
      })
      throw upErr
    }
  }

  async deactivatePropertyStaffAssignment(input: {
    propertyId: string
    staffId: string
  }): Promise<void> {
    const { data: row, error: fetchErr } = await this.supabase
      .from('property_staff')
      .select('id, role, status')
      .eq('id', input.staffId)
      .eq('property_id', input.propertyId)
      .maybeSingle()

    if (fetchErr) {
      console.error('[StaffManagementQueries] Failed to load staff row for deactivate', {
        propertyId: input.propertyId,
        staffId: input.staffId,
        error: fetchErr,
      })
      throw fetchErr
    }

    if (!row) {
      throw new Error('Staff assignment not found')
    }

    const currentRole = (row.role ?? '').toLowerCase()
    if (currentRole === 'owner') {
      throw new Error('Cannot deactivate property owner from staff management')
    }

    const currentStatus = (row.status ?? '').toLowerCase()
    if (currentStatus === 'inactive') {
      throw new Error('Staff member is already inactive')
    }

    const { error: upErr } = await this.supabase
      .from('property_staff')
      .update({ status: 'inactive' })
      .eq('id', input.staffId)
      .eq('property_id', input.propertyId)

    if (upErr) {
      console.error('[StaffManagementQueries] Failed to deactivate property staff', {
        propertyId: input.propertyId,
        staffId: input.staffId,
        error: upErr,
      })
      throw upErr
    }
  }

  async reactivatePropertyStaffAssignment(input: {
    propertyId: string
    staffId: string
  }): Promise<void> {
    const { data: row, error: fetchErr } = await this.supabase
      .from('property_staff')
      .select('id, role, status')
      .eq('id', input.staffId)
      .eq('property_id', input.propertyId)
      .maybeSingle()

    if (fetchErr) {
      console.error('[StaffManagementQueries] Failed to load staff row for reactivate', {
        propertyId: input.propertyId,
        staffId: input.staffId,
        error: fetchErr,
      })
      throw fetchErr
    }

    if (!row) {
      throw new Error('Staff assignment not found')
    }

    const currentRole = (row.role ?? '').toLowerCase()
    if (currentRole === 'owner') {
      throw new Error('Cannot change property owner status from staff management')
    }

    const currentStatus = (row.status ?? '').toLowerCase()
    if (currentStatus !== 'inactive') {
      throw new Error('Only inactive staff members can be reactivated')
    }

    const { error: upErr } = await this.supabase
      .from('property_staff')
      .update({ status: 'active' })
      .eq('id', input.staffId)
      .eq('property_id', input.propertyId)

    if (upErr) {
      console.error('[StaffManagementQueries] Failed to reactivate property staff', {
        propertyId: input.propertyId,
        staffId: input.staffId,
        error: upErr,
      })
      throw upErr
    }
  }
}

"use client"

import { ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from "lucide-react"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

const DEFAULT_WINDOW = 2

function getPageItems(
  currentPage: number,
  totalPages: number,
  windowSize: number
): (number | "ellipsis")[] {
  if (totalPages <= 0) return []
  if (totalPages === 1) return [1]

  const rangeStart = Math.max(1, currentPage - windowSize)
  const rangeEnd = Math.min(totalPages, currentPage + windowSize)
  const items: (number | "ellipsis")[] = []

  if (rangeStart > 1) {
    items.push(1)
    if (rangeStart > 2) items.push("ellipsis")
  }
  for (let p = rangeStart; p <= rangeEnd; p++) {
    items.push(p)
  }
  if (rangeEnd < totalPages) {
    if (rangeEnd < totalPages - 1) items.push("ellipsis")
    items.push(totalPages)
  }
  return items
}

export type PaginationProps = {
  currentPage: number
  totalPages: number
  onPageChange: (page: number) => void
  disabled?: boolean
  windowSize?: number
  className?: string
}

export function Pagination({
  currentPage,
  totalPages,
  onPageChange,
  disabled = false,
  windowSize = DEFAULT_WINDOW,
  className,
}: PaginationProps) {
  const pageItems = getPageItems(currentPage, totalPages, windowSize)
  const canPrev = currentPage > 1
  const canNext = currentPage < totalPages

  return (
    <nav
      role="navigation"
      aria-label="Pagination"
      className={cn("flex items-center gap-1", className)}
    >
      <Button
        variant="outline"
        size="icon"
        className="h-8 w-8 rounded-sm bg-card/50"
        onClick={() => onPageChange(1)}
        disabled={!canPrev || disabled}
        aria-label="First page"
      >
        <ChevronsLeft className="h-4 w-4" />
      </Button>
      <Button
        variant="outline"
        size="icon"
        className="h-8 w-8 rounded-sm bg-card/50"
        onClick={() => onPageChange(currentPage - 1)}
        disabled={!canPrev || disabled}
        aria-label="Previous page"
      >
        <ChevronLeft className="h-4 w-4" />
      </Button>

      <div className="flex items-center gap-1 px-1">
        {pageItems.map((item, i) =>
          item === "ellipsis" ? (
            <span
              key={`ellipsis-${i}`}
              className="flex h-8 w-8 items-center justify-center text-xs text-muted-foreground"
              aria-hidden
            >
              …
            </span>
          ) : (
            <Button
              key={item}
              variant={currentPage === item ? "default" : "outline"}
              size="icon"
              className={cn(
                "h-8 w-8 min-w-8 rounded-sm text-xs",
                currentPage === item ? "" : "bg-card/50"
              )}
              onClick={() => onPageChange(item)}
              disabled={disabled}
              aria-label={`Page ${item}`}
              aria-current={currentPage === item ? "page" : undefined}
            >
              {item}
            </Button>
          )
        )}
      </div>

      <Button
        variant="outline"
        size="icon"
        className="h-8 w-8 rounded-sm bg-card/50"
        onClick={() => onPageChange(currentPage + 1)}
        disabled={!canNext || disabled}
        aria-label="Next page"
      >
        <ChevronRight className="h-4 w-4" />
      </Button>
      <Button
        variant="outline"
        size="icon"
        className="h-8 w-8 rounded-sm bg-card/50"
        onClick={() => onPageChange(totalPages)}
        disabled={!canNext || disabled}
        aria-label="Last page"
      >
        <ChevronsRight className="h-4 w-4" />
      </Button>
    </nav>
  )
}

"use client"

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"

type PageSizeSelectorProps = {
  value: number
  onChange: (value: number) => void
  disabled?: boolean
  options?: number[]
  className?: string
}

export function PageSizeSelector({
  value,
  onChange,
  disabled = false,
  options = [10, 25, 50, 100],
  className,
}: PageSizeSelectorProps) {
  return (
    <div className={`flex items-center gap-2 text-xs text-muted-foreground ${className ?? ""}`}>
      <span>Show</span>
      <Select
        value={String(value)}
        onValueChange={(val) => {
          const next = Number(val)
          if (!Number.isFinite(next) || next <= 0) return
          onChange(next)
        }}
        disabled={disabled}
      >
        <SelectTrigger className="h-8 w-[70px] rounded-sm bg-card/50 px-2 text-xs">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {options.map((option) => (
            <SelectItem key={option} value={String(option)}>
              {option}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <span>per page</span>
    </div>
  )
}

import AuditingPageHeader from "@/components/dashboard/auditing/auditing-page-header"
import AuditingFilter from "@/components/dashboard/auditing/auditing-filter"
import AuditingTable from "@/components/dashboard/auditing/auditing-table"
import { createClient } from "@/lib/supabase/server"
import { getPropertyActivityLogs } from "@/lib/dashboard/queries"
import { getPropertyForUser } from "@/lib/dashboard/property-access"
import { resolveDashboardNavVisibility } from "@/lib/dashboard/dashboard-layout-context"
import { redirect } from "next/navigation"

type pageProps = {
    params: Promise<{ propertyId: string }>
    searchParams: Promise<{
        page?: string
        pageSize?: string
        q?: string
        action?: string
        resource?: string
        dateFrom?: string
        dateTo?: string
        sortBy?: string
        sortOrder?: string
        [key: string]: string | string[] | undefined
    }>
}

function isValidYmd(value: string): boolean {
    return /^\d{4}-\d{2}-\d{2}$/.test(value)
}

export default async function AuditingPage({ params, searchParams }: pageProps) {
    const { propertyId } = await params

    const property = await getPropertyForUser(propertyId)
    if (!property) redirect("/auth/login")

    const supabase = await createClient()
    const {
        data: { user },
    } = await supabase.auth.getUser()
    if (!user) redirect("/auth/login")
    const navVisibility = await resolveDashboardNavVisibility(supabase, propertyId, user.id)
    if (!navVisibility.moduleNavVisible.auditing) {
        redirect(`/dashboard/${propertyId}/access-denied`)
    }

    const sp = await searchParams

    const currentPage = Number.isNaN(Number(sp.page)) || !sp.page ? 1 : Math.max(1, Number(sp.page))
    const parsedPageSize =
